#!/usr/bin/env python3
import hashlib, html, io, json, runpy, time, urllib.parse, urllib.request
from pathlib import Path
from PIL import Image
base=runpy.run_path(str(Path(__file__).with_name('publish_recipe_20260825_1000.py')),run_name='recipe_base')
TITLE='Iogurte Natural com Pera para Bebê: Lanche sem Açúcar'; SLUG_KEY='iogurte-natural-pera-bebe-sem-acucar'; CLUSTER='Cluster 3 — Café da manhã e lanches sem açúcar'; KEYWORD='iogurte natural com pera para bebê'
MARKER=base['MARKER']; BLOG_ID=base['BLOG_ID']; COVER_DIR=base['COVER_DIR']; RAW_BASE=base['RAW_BASE']; LOG_PATH=base['LOG_PATH']; RESULT_PATH=base['RESULT_PATH']; W,H=1200,630

def generate_cover(path):
 p="Photorealistic horizontal food photograph of plain natural unsweetened yogurt with soft mashed ripe pear for a baby-friendly snack, thick white plain yogurt in a small matte pale ceramic bowl with visibly mashed tender pear gently folded through it, a few tiny soft pear pieces on top, simple homemade serving, warm evening natural window light, light oak table, neutral linen, realistic texture, close three-quarter food photography. No granola, honey, sugar, syrup, nuts, seeds, packaging, baby, child, people, hands, text, logo, watermark, collage, illustration or cartoon."
 enc=urllib.parse.quote(p,safe=''); seed=int(hashlib.sha256(TITLE.encode()).hexdigest()[:12],16)%2147483647; last=None
 for a in range(8):
  try:
   u=f'https://image.pollinations.ai/prompt/{enc}?width={W}&height={H}&model=flux&nologo=true&safe=true&enhance=true&seed={seed+a*10007}'; req=urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0 (compatible; ReceitasParaPequenos/3.0)','Accept':'image/*'})
   with urllib.request.urlopen(req,timeout=240) as r: raw=r.read()
   if len(raw)<15000: raise RuntimeError('small image response')
   im=Image.open(io.BytesIO(raw)).convert('RGB'); tr=W/H; cr=im.width/im.height
   if cr>tr: nw=int(im.height*tr); x=(im.width-nw)//2; im=im.crop((x,0,x+nw,im.height))
   elif cr<tr: nh=int(im.width/tr); y=(im.height-nh)//2; im=im.crop((0,y,im.width,y+nh))
   im=im.resize((W,H),Image.Resampling.LANCZOS); path.parent.mkdir(parents=True,exist_ok=True); im.save(path,'JPEG',quality=92,optimize=True,progressive=True); return
  except Exception as e: last=e; time.sleep(min(10*(a+1),45))
 raise RuntimeError(f'cover generation failed: {last}')

def article(cover):
 schema={'@context':'https://schema.org','@type':'Recipe','name':TITLE,'image':[cover],'author':{'@type':'Organization','name':'Equipe Editorial do Receitas Para Pequenos'},'description':'Lanche simples de iogurte natural integral sem açúcar com pera madura amassada, com textura adaptável.','recipeCategory':'Lanche','recipeCuisine':'Brasileira','keywords':KEYWORD+', lanche sem açúcar, iogurte com fruta','recipeYield':'1 pequena porção','recipeIngredient':['3 colheres (sopa) de iogurte natural integral sem açúcar','1/4 de pera bem madura, sem sementes, amassada ou cozida até ficar macia'],'recipeInstructions':[{'@type':'HowToStep','text':'Prepare a pera em textura macia adequada às habilidades da criança.'},{'@type':'HowToStep','text':'Coloque o iogurte natural em uma tigela limpa.'},{'@type':'HowToStep','text':'Misture a pera amassada ao iogurte e sirva imediatamente.'}]}
 sj=json.dumps(schema,ensure_ascii=False).replace('</','<\\/'); alt=html.escape(TITLE,quote=True)
 return f"""{MARKER}<div class='separator' style='clear:both;margin:0 0 24px;text-align:center'><img alt='{alt}' data-original-height='630' data-original-width='1200' src='{cover}' style='border-radius:14px;height:auto;max-width:100%;width:1200px'/></div><p><strong>Por Equipe Editorial do Receitas Para Pequenos</strong></p><p>Iogurte natural com pera é uma combinação curta e prática para variar o lanche sem adicionar açúcar. A pera madura entra amassada para dar sabor e permitir que a textura seja ajustada às habilidades da criança.</p><p><strong>Atenção:</strong> adapte consistência e tamanho de eventuais pedacinhos às habilidades da criança e ofereça sempre com ela sentada e supervisionada. Alergias, dificuldades de mastigação/deglutição e necessidades especiais exigem orientação profissional individualizada.</p><h2>Ingredientes</h2><ul><li>3 colheres (sopa) de iogurte natural integral sem açúcar</li><li>1/4 de pera bem madura, sem sementes, amassada</li></ul><h2>Modo de preparo</h2><ol><li>Lave a pera, retire sementes e partes duras.</li><li>Se estiver bem madura e macia, amasse até chegar à textura desejada. Se ainda estiver firme, cozinhe até ficar bem macia e deixe esfriar antes de amassar.</li><li>Coloque o iogurte em uma tigela limpa.</li><li>Misture a pera amassada ao iogurte e sirva em seguida.</li></ol><h2>Como deve ficar a textura</h2><p>A mistura pode ficar cremosa e homogênea ou conter pequenos pedaços muito macios de pera, conforme as habilidades da criança. Não é necessário liquidificar tudo: a consistência deve ser adaptada individualmente.</p><h2>Como escolher o iogurte</h2><p>Para esta receita, use iogurte natural integral sem açúcar adicionado. Confira a lista de ingredientes do produto e evite versões adoçadas ou com coberturas. O Ministério da Saúde orienta não oferecer açúcar nem preparações com açúcar para crianças menores de 2 anos.</p><h2>Como servir e adaptar</h2><p>Sirva em pequena quantidade, sem mel, açúcar, xaropes, granola ou castanhas. A pera deve estar suficientemente macia para a textura escolhida. Se houver dúvida sobre alergia à proteína do leite ou outra condição individual, procure profissional habilitado antes de oferecer.</p><h2>Posso trocar a pera?</h2><p>Para variar o sabor em outra ocasião, frutas maduras e macias podem compor preparações diferentes, mas esta página foi pensada especificamente para pera. A adaptação de textura continua sendo necessária em qualquer substituição.</p><h2>Perguntas frequentes</h2><h3>Precisa colocar açúcar?</h3><p>Não. A receita usa apenas o sabor natural da pera e foi planejada sem açúcar adicionado.</p><h3>Posso usar iogurte sabor pera?</h3><p>Esta receita usa iogurte natural sem açúcar e a própria fruta. Produtos saborizados podem ter composição diferente, por isso vale conferir o rótulo.</p><h3>Preciso bater no liquidificador?</h3><p>Não. A pera pode ser amassada e misturada ao iogurte, ajustando a consistência às habilidades da criança.</p><h2>Receitas relacionadas</h2><ul><li><a href='https://www.receitasparapequenos.site/2026/08/panqueca-de-pera-e-aveia-sem-acucar.html'>Panqueca de Pera e Aveia sem Açúcar para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/muffin-de-maca-e-aveia-sem-acucar-para.html'>Muffin de Maçã e Aveia sem Açúcar para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/pao-de-cenoura-caseiro-para-bebe.html'>Pão de Cenoura Caseiro para Bebê</a></li></ul><h2>Referências oficiais</h2><ul><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-crianca/primeira-infancia/alimentacao-saudavel' rel='nofollow'>Ministério da Saúde — Alimentação saudável na primeira infância</a></li><li><a href='https://www.gov.br/saude/pt-br/composicao/saps/promocao-da-saude/guias-alimentares/publicacoes/guia_da_crianca_2019.pdf/view' rel='nofollow'>Ministério da Saúde — Guia Alimentar para Crianças Brasileiras Menores de 2 Anos</a></li></ul><h2>Conclusão</h2><p>Com apenas iogurte natural sem açúcar e pera madura, este lanche oferece uma forma simples de variar o cardápio mantendo a preparação curta e a textura ajustável.</p><script type='application/ld+json'>{sj}</script>"""

def main():
 tok=base['token'](); posts=base['list_posts'](tok)
 for p in posts:
  t=(p.get('title') or '').casefold()
  if t==TITLE.casefold() or ('iogurte' in t and 'pera' in t):
   RESULT_PATH.write_text(f'outcome=skipped_duplicate\ntitle={p.get("title","")}\nurl={p.get("url","")}\n',encoding='utf-8'); base['git_commit_push']([RESULT_PATH],'Record duplicate prevention for yogurt pear'); return
 suffix=hashlib.sha1(TITLE.encode()).hexdigest()[:10]; cp=COVER_DIR/f'{SLUG_KEY}-{suffix}.jpg'; cu=f'{RAW_BASE}/{cp.name}'
 if not cp.exists(): generate_cover(cp); base['git_commit_push']([cp],'Add unique AI food photo for yogurt pear'); time.sleep(8)
 content=article(cu)
 if MARKER not in content or cu not in content: raise RuntimeError('cover verification failed before publish')
 created=base['api'](tok,'POST',f'/blogs/{BLOG_ID}/posts',{'isDraft':'false','fetchBody':'true'},{'kind':'blogger#post','blog':{'id':BLOG_ID},'title':TITLE,'content':content,'labels':['Alimentação complementar','Café da manhã','Lanche','Sem açúcar','Iogurte','Pera']}); pid=str(created.get('id','')); url=created.get('url','')
 if not pid: raise RuntimeError('Blogger did not return post id')
 vc=(base['api'](tok,'GET',f'/blogs/{BLOG_ID}/posts/{pid}',{'view':'ADMIN'}).get('content') or '')
 if MARKER not in vc or cu not in vc: raise RuntimeError('live Blogger post failed cover verification')
 log=base['load_log'](); log.append({'published_at':created.get('published'),'title':TITLE,'url':url,'post_id':pid,'cluster':CLUSTER,'keyword':KEYWORD,'cover_url':cu,'marker':MARKER}); LOG_PATH.write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); RESULT_PATH.write_text('outcome=success\n'+f'title={TITLE}\nurl={url}\npost_id={pid}\ncluster={CLUSTER}\ncover_url={cu}\nmarker_verified=true\n',encoding='utf-8'); base['git_commit_push']([LOG_PATH,RESULT_PATH],'Record published yogurt pear recipe')
if __name__=='__main__': main()
